#include "gigasecond.h"
#include <iostream>
using boost::posix_time::time_from_string;
using boost::posix_time::ptime;
int fails = 0;
void chk(const char* in, const char* exp) {
    ptime a = gigasecond::advance(time_from_string(in));
    ptime e = time_from_string(exp);
    bool ok = (a == e);
    if (!ok) ++fails;
    std::cout << (ok ? "OK   " : "FAIL ") << in << " -> " << a << " (expected " << exp << ")\n";
}
int main() {
    chk("2015-01-24 22:00:00", "2046-10-02 23:46:40");
    chk("2015-01-24 23:59:59", "2046-10-03 01:46:39");
    chk("2011-04-25 00:00:00", "2043-01-01 01:46:40");
    chk("2000-02-29 12:00:00", "2031-11-07 13:46:40");
    chk("1970-01-01 00:00:00", "2001-09-09 01:46:40");
    std::cout << (fails ? "FAILURES\n" : "ALL BOUNDARY CHECKS PASSED\n");
    return fails;
}
EOF
